 rows.append({'review_id':bid,'new_material':kind!='none','binding':kind!='none','direct':kind=='direct','bridge':kind=='bridge','support_refs':refs,'reason':reason,'query_drift':False if x['query'] else None,'candidate_commitment':False if x['query'] else None,'objective_only_rule_violation':bid in extra,'objective_only_reason':extra.get(bid),'ambiguity':'medium' if bid in ['E004','E013','E016','E017','E018'] else 'low'})
